/* SaikoSubStudio service worker — generated by scripts/pwa/build-sw.mjs. Do not edit public/sw.js. */
/* eslint-disable */
'use strict';

const SW_VERSION = __SW_VERSION__;
const PRECACHE_REQUIRED = __PRECACHE_REQUIRED__;
const PRECACHE_OPTIONAL = __PRECACHE_OPTIONAL__;

const CACHE_PREFIX = 'saiko-';
const PRECACHE = `${CACHE_PREFIX}precache-${SW_VERSION}`;
const PAGES = `${CACHE_PREFIX}pages-${SW_VERSION}`;
const RUNTIME = `${CACHE_PREFIX}runtime-${SW_VERSION}`;
const SHELL_URL = '/';
const NAV_TIMEOUT_MS = 4000;

// Never intercept or cache: API routes (TMDB proxy /api/tmdb/*, feedback), the SW itself.
// Cross-origin requests (image.tmdb.org, api.themoviedb.org, Cloudflare beacon, …) are
// never intercepted either — see isBypassed().
const BYPASS_PATH_PREFIXES = ['/api/', '/sw.js', '/cdn-cgi/'];
const STATIC_EXT = /\.(?:js|mjs|css|woff2?|ttf|otf|png|jpe?g|gif|svg|webp|avif|ico|wasm|webmanifest)$/i;

function isBypassed(request, url) {
  if (request.method !== 'GET') return true;
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return true; // blob:, data:, …
  if (url.origin !== self.location.origin) return true; // TMDB & any third party
  if (/(^|\.)tmdb\.org$|(^|\.)themoviedb\.org$/i.test(url.hostname)) return true;
  if (BYPASS_PATH_PREFIXES.some((p) => url.pathname.startsWith(p))) return true;
  if (request.headers.has('range')) return true;
  // Next.js RSC / prefetch payloads: let them hit the network; on failure Next falls
  // back to a hard navigation, which the navigation handler serves from cache.
  if (url.searchParams.has('_rsc') || request.headers.get('RSC') === '1') return true;
  return false;
}

function cacheable(response) {
  return response && response.ok && response.type === 'basic' && !response.redirected;
}

async function precacheAll() {
  const cache = await caches.open(PRECACHE);
  // Required: app shell + every hashed Next.js asset (incl. lazily loaded chunks).
  await cache.addAll(PRECACHE_REQUIRED.map((u) => new Request(u, { cache: 'reload' })));
  // Optional (fonts, preview scenes, icons): best effort, never fail install.
  await Promise.allSettled(
    PRECACHE_OPTIONAL.map(async (u) => {
      const res = await fetch(new Request(u, { cache: 'reload' }));
      if (cacheable(res)) await cache.put(u, res);
    }),
  );
}

self.addEventListener('install', (event) => {
  // No skipWaiting() here: an update waits until the user clicks “刷新” in the page.
  event.waitUntil(precacheAll());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keep = new Set([PRECACHE, PAGES, RUNTIME]);
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith(CACHE_PREFIX) && !keep.has(k)).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const data = event.data;
  if (data && data.type === 'SKIP_WAITING') self.skipWaiting();
  if (data && data.type === 'GET_VERSION' && event.ports && event.ports[0]) {
    event.ports[0].postMessage({ version: SW_VERSION });
  }
});

async function matchAny(request, options) {
  // Search our own caches first (current version), then any saiko-* cache (e.g. a
  // freshly installed waiting worker that already holds the next build's chunks).
  const own = await caches.match(request, { cacheName: PRECACHE, ...options });
  if (own) return own;
  return caches.match(request, options);
}

async function cacheFirst(request) {
  const hit = await matchAny(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (cacheable(res)) {
    const cache = await caches.open(RUNTIME);
    cache.put(request, res.clone());
  }
  return res;
}

async function staleWhileRevalidate(event, request) {
  const hit = (await matchAny(request)) || (await matchAny(request, { ignoreSearch: true }));
  const network = fetch(request).then(async (res) => {
    if (cacheable(res)) {
      const cache = await caches.open(RUNTIME);
      await cache.put(request, res.clone());
    }
    return res;
  });
  if (hit) {
    event.waitUntil(network.catch(() => undefined));
    return hit;
  }
  return network;
}

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));
}

async function networkFirstNavigation(event, request, url) {
  const key = url.origin + url.pathname; // ignore query strings for page cache keys
  try {
    const res = await Promise.race([fetch(request), timeout(NAV_TIMEOUT_MS)]);
    if (cacheable(res) && (res.headers.get('content-type') || '').includes('text/html')) {
      const copy = res.clone();
      event.waitUntil(caches.open(PAGES).then((c) => c.put(key, copy)));
    }
    return res;
  } catch (err) {
    const cached =
      (await caches.match(key, { cacheName: PAGES })) ||
      (await matchAny(key)) ||
      (await caches.match(SHELL_URL, { cacheName: PAGES })) ||
      (await matchAny(SHELL_URL));
    if (cached) return cached;
    return new Response(
      '<!doctype html><meta charset="utf-8"><title>离线</title><p style="font-family:system-ui;padding:2rem">当前离线，且尚未缓存此页面。联网打开一次后即可离线使用。</p>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } },
    );
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  let url;
  try { url = new URL(request.url); } catch { return; }
  if (isBypassed(request, url)) return; // browser handles it; nothing is cached

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(event, request, url));
    return;
  }
  if (url.pathname.startsWith('/_next/static/')) {
    event.respondWith(cacheFirst(request));
    return;
  }
  if (STATIC_EXT.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(event, request));
  }
  // Anything else same-origin (e.g. unknown GET endpoints) goes straight to network.
});
